from content_common import *
lesson('py-trace','Laços: execute na ordem, incluindo continue e break','Uma pequena tabela de execução é mais segura que imaginar a saída inteira.', ['range(a,b) inclui a e exclui b. continue pula o restante da iteração atual; break encerra o laço mais próximo. Um else associado ao laço executa quando ele termina sem break, inclusive quando não há iteração.','Registre o valor do acumulador após cada linha que o altera. Não execute linhas que ficaram depois de continue ou break naquela passagem.'], 's=0\nfor n in range(1,5):\n    if n == 2:\n        continue\n    s += n\n# Soma 1, 3 e 4: resultado 8.', ['Liste os valores produzidos pelo range.','Teste a condição antes de atualizar o acumulador.','Pule corretamente linhas após continue.','Verifique se houve break antes de executar o else.'], 'O else do for não significa “a condição do if foi falsa”.', 'Python 3 — Tutorial, Control Flow')
pair('Python e Ferramentas','Trace de continue','py-trace',case('Qual valor é impresso pelo código Python 3?', ['7','15','9','6','8'], 'range(1,6) produz 1,2,3,4,5. O continue pula n=3; o break em n=5 vem antes da soma. Portanto, s=1+2+4=7.', ['Não segue a posição do break.','Soma valores que não chegam ao acumulador.','Ignora a ordem de execução.','Conta um conjunto diferente de iterações.'],code='s = 0\nfor n in range(1, 6):\n    if n == 3:\n        continue\n    if n == 5:\n        break\n    s += n\nprint(s)',check={'kind':'python','stdout':'7'}),case('Qual valor é impresso pelo código Python 3?', ['8','7','3','4','10'], 'O laço encontra n=4 e executa break. A variável s estava em 8 após processar n=2 e n=3; o else não é executado porque houve break.', ['Ignora uma atualização do acumulador.','Confunde o último valor processado com a soma.','É o valor de n que aciona o break.','Executa incorretamente parte do else.'],code='s = 3\nfor n in range(2, 5):\n    if n == 4:\n        break\n    s += n\nelse:\n    s += 10\nprint(s)',check={'kind':'python','stdout':'8'}))
lesson('py-func','Funções: retorno, mutação e argumentos padrão','Retornar um valor e alterar um objeto recebido são operações diferentes.', ['Listas são mutáveis. Alterar uma lista compartilhada pode ser observado por outras referências ao mesmo objeto. Reatribuir um nome local, por outro lado, não reatribui automaticamente o nome usado pelo chamador.','O valor padrão de um parâmetro é avaliado quando a definição da função é executada, não a cada chamada. Uma lista padrão pode acumular conteúdo entre chamadas. Para uma lista nova por chamada, use None e crie a lista dentro da função.'], 'def adicionar(x, itens=None):\n    if itens is None:\n        itens = []\n    itens.append(x)\n    return itens\n# Chamadas sem a lista explícita recebem listas distintas.', ['Identifique quais nomes apontam para o mesmo objeto.','Separe mutação de reatribuição.','Verifique quando o valor padrão foi criado.','Anote o valor retornado em cada chamada.'], 'Uma função sem return explícito retorna None.', 'Python 3 — Tutorial, Default Argument Values')
pair('Python e Ferramentas','Argumento padrão mutável','py-func',case('Qual é a saída deste programa Python 3?', ['[1] [1, 2]','[1] [2]','[1, 2] [1, 2]','None None','[2] [1]'], 'A primeira chamada usa a lista padrão, acrescenta 1 e retorna uma cópia [1]. A segunda reutiliza a lista padrão e acrescenta 2, retornando [1,2]. A cópia guardada em a não muda.', ['Supõe que a lista padrão é recriada em cada chamada.','Ignora que o retorno usa copy(), isolando a primeira lista retornada.','Há return explícito.','Inverte a sequência de chamadas.'],code='def f(x, itens=[]):\n    itens.append(x)\n    return itens.copy()\na = f(1)\nb = f(2)\nprint(a, b)',check={'kind':'python','stdout':'[1] [1, 2]'}),case('Qual é a saída deste programa Python 3?', ['[1, 2, 3] [9]','[9] [9]','[1, 2] [9]','[1, 2, 3] None','[1, 2, 3, 9] [9]'], 'append modifica a lista original, que vira [1,2,3]. Depois xs=[9] reatribui apenas o nome local; o retorno é essa nova lista, enquanto a continua apontando para a original.', ['Reatribuição local não troca a referência do chamador.','Ignora a mutação anterior à reatribuição.','A função retorna explicitamente xs.','Reatribuir não equivale a acrescentar à lista original.'],code='def f(xs):\n    xs.append(3)\n    xs = [9]\n    return xs\na = [1, 2]\nb = f(a)\nprint(a, b)',check={'kind':'python','stdout':'[1, 2, 3] [9]'}))
lesson('py-numpy','NumPy: forma antes do cálculo','Broadcasting compara dimensões da direita para a esquerda: iguais ou uma delas igual a 1.', ['Em operações elemento a elemento, dimensões compatíveis podem ser expandidas conceitualmente. Um vetor de forma (3,) pode operar com uma matriz (2,3), repetindo-se pelas linhas. Formas (2,3) e (2,) não são compatíveis por essa regra.','O operador * é multiplicação elemento a elemento; @ faz produto matricial para matrizes 2D. Para Ax, alinhe colunas de A com o tamanho de x. Slicing básico pode produzir uma visão que compartilha dados com o original.'], 'np.array([[1,2],[3,4]]) + np.array([10,20]) resulta em [[11,22],[13,24]]. O vetor é alinhado às colunas, não às linhas.', ['Escreva as formas dos operandos.','Compare dimensões desde a direita.','Identifique se o operador é * ou @.','Só então calcule os elementos ou a forma da saída.'], 'Mesmo resultado de forma não significa mesma operação.', 'NumPy — Broadcasting e Indexing')
pair('Python e Ferramentas','Broadcasting e soma por eixo','py-numpy',case('Qual é a lista impressa, usando NumPy?', ['[15, 27, 39]','[16, 26, 36]','[11, 12, 13]','[10, 20, 30]','O código falha por broadcasting incompatível.'], 'axis=0 soma as linhas em cada coluna: [5,7,9]. O vetor b tem a mesma forma (3,); a soma elemento a elemento resulta em [15,27,39].', ['Aplica somas por eixo incorreto.','Ignora a segunda linha.','Não considera os valores da matriz.','As formas (3,) e (3,) são compatíveis.'],code='import numpy as np\na = np.array([[1, 2, 3], [4, 5, 6]])\nb = np.array([10, 20, 30])\nprint((a.sum(axis=0) + b).tolist())',check={'kind':'python','stdout':'[15, 27, 39]'}),case('Para arrays NumPy com formas (4,3) e (4,), uma soma direta elemento a elemento:', ['falha por incompatibilidade entre as dimensões finais 3 e 4.','sempre soma o vetor a cada coluna automaticamente.','produz forma (4,4).','produz forma (3,).','equivale necessariamente a um produto matricial.'], 'Comparando da direita, 3 e 4 são diferentes e nenhuma é 1. Para somar um valor por linha, o vetor poderia ser remodelado para (4,1).', ['Esse alinhamento exigiria forma (4,1).','Não há broadcasting válido que produza essa forma.','Não há redução de dimensão por soma entre arrays.','Adição elemento a elemento não é produto matricial.']))
lesson('py-pandas','Pandas: junção pode multiplicar linhas','Uma chave duplicada dos dois lados gera todas as combinações correspondentes.', ['Em merge por uma chave, se um valor aparece m vezes à esquerda e n vezes à direita, ele pode produzir m×n linhas. Isso pode ser correto para muitos-para-muitos ou indicar um problema de modelagem.','A agregação deve vir depois de entender a granularidade. count() conta valores não nulos de uma coluna; size() conta linhas do grupo. As duas medidas divergem quando existem valores ausentes.'], 'Duas vendas do cliente X e três registros cadastrais de X geram seis combinações na junção. Somar valores de venda depois disso pode triplicar o total.', ['Conte a frequência de cada chave dos dois lados.','Identifique a cardinalidade esperada.','Cheque se houve multiplicação antes de agregar.','Separe contagem de linhas de contagem de valores presentes.'], 'merge não remove duplicidades automaticamente.', 'pandas — Merge, join, concatenate and compare')
pair('Python e Ferramentas','Merge muitos-para-muitos','py-pandas',case('Um inner merge é feito pela chave k. À esquerda, k=1 aparece em 2 linhas e k=2 em 1; à direita, k=1 aparece em 3 linhas e k=2 em 2. Quantas linhas são produzidas?', ['8.','5.','6.','3.','10.'], 'Para k=1, 2×3=6; para k=2, 1×2=2. Total 8 combinações correspondentes.', ['Conta linhas de apenas um dos lados.','Conta somente a primeira chave.','Conta linhas da esquerda sem expansão.','Multiplica totais sem restringir por chave.']),case('Um grupo de DataFrame tem 4 linhas, com valores de x iguais a 10, ausente, 20 e ausente. Para esse grupo, size() e x.count() retornam:', ['4 e 2.','2 e 4.','4 e 4.','2 e 2.','30 e 2.'], 'size conta todas as linhas; count em x exclui os dois valores ausentes. Soma 30 é outra agregação.', ['Inverte os critérios.','count não inclui ausentes.','size não exclui linhas por ausência em x.','Confunde contagem com soma.']))
lesson('py-spark','Spark: transformação é plano; ação pede resultado','Transformações de RDD são avaliadas de forma preguiçosa; uma ação dispara a computação necessária.', ['map e filter produzem novos RDDs descritos por transformações. Ações como count ou collect exigem resultados. Sem persistência efetiva, ações posteriores podem recomputar a linhagem.','collect leva todos os elementos ao driver e pode exceder sua memória. count devolve uma contagem escalar. Cache não transforma um conjunto arbitrariamente grande em algo que cabe no driver.'], 'rdd.filter(condicao) descreve uma seleção. filtered.count() pede a quantidade; filtered.collect() pede cada elemento para o processo coordenador. São custos de transferência distintos.', ['Classifique cada operação como transformação ou ação.','Identifique onde o resultado ficará.','Verifique se há shuffle ou transferência volumosa.','Use persistência quando a reutilização e os recursos justificarem.'], 'Distribuído no processamento não significa ilimitado ao coletar no driver.', 'Apache Spark — RDD Programming Guide')
pair('Python e Ferramentas','Avaliação preguiçosa no Spark','py-spark',case('Após criar um RDD, são chamadas map e filter, sem ação. No modelo de execução de RDD do Spark:', ['essas transformações descrevem uma computação cuja avaliação é disparada quando uma ação exige resultado.','cada transformação necessariamente devolve todos os dados ao driver.','filter é uma ação que sempre retorna um inteiro.','map elimina automaticamente qualquer shuffle futuro.','o plano não pode ser reutilizado por nenhuma ação.'], 'RDDs usam avaliação preguiçosa das transformações. Uma ação materializa o resultado necessário à execução.', ['Transformações não implicam collect.','filter retorna um RDD transformado.','map não garante ausência de shuffle em operações posteriores.','A linhagem pode atender a ações; persistência pode ajudar na reutilização.']),case('Um RDD distribuído é muito maior que a memória do driver. O analista só precisa saber o total de elementos. A operação mais apropriada entre as opções é:', ['count(), que retorna uma contagem em vez de trazer todos os elementos.','collect(), porque a distribuição garante memória infinita no driver.','collect() seguido de len(), sempre sem risco de memória.','map(), pois retorna automaticamente um inteiro com a quantidade.','cache(), que retorna por definição o número de elementos.'], 'count solicita uma agregação escalar. collect transfere os elementos ao driver, onde o limite de memória continua existindo.', ['Distribuição não elimina o limite local.','A transferência total pode exceder a memória.','map é transformação, não contagem.','cache marca persistência, não substitui uma ação de contagem.']))
lesson('db-join','SQL: preserve linhas sem correspondência','LEFT JOIN mantém linhas da esquerda; um filtro posterior pode remover justamente as linhas sem par.', ['ON define quais pares correspondem na junção. WHERE filtra as linhas já produzidas. Em LEFT JOIN, linhas sem par recebem NULL no lado direito; comparar essa coluna a um valor no WHERE não resulta em verdadeiro para essas linhas.','Para manter entidades sem ocorrências, restrinja ocorrências no ON quando esse for o objetivo. COUNT(coluna_direita) não conta NULL; COUNT(*) conta também a linha preservada do lado esquerdo.'], 'Clientes LEFT JOIN Pedidos ON id e status="pago" mantém clientes sem pedido pago. Mover status="pago" para WHERE elimina esses clientes do resultado.', ['Defina quais entidades precisam permanecer.','Coloque a condição de correspondência no ON.','Avalie o efeito de NULL no WHERE.','Escolha COUNT(*) ou COUNT(coluna) conscientemente.'], 'WHERE sobre o lado opcional pode fazer um LEFT JOIN se comportar como INNER JOIN para o filtro.', 'SQL relacional; PostgreSQL — Joins Between Tables')
pair('Banco de Dados','LEFT JOIN e COUNT','db-join',case('Clientes tem ids 1 e 2. Pedidos tem duas linhas do cliente 1 e nenhuma do cliente 2. Em LEFT JOIN por cliente, agrupando por id do cliente, COUNT(*) e COUNT(Pedidos.id) para o cliente 2 são:', ['1 e 0.','0 e 0.','1 e 1.','2 e 0.','0 e 1.'], 'A junção preserva uma linha do cliente 2, preenchendo o lado Pedidos com NULL. COUNT(*) conta a linha; COUNT(Pedidos.id) não conta o NULL.', ['Ignora a linha preservada.','Conta NULL como valor presente.','As duas linhas pertencem ao cliente 1.','Inverte a diferença entre os tipos de contagem.']),case('Deseja-se listar todos os clientes e seus pedidos pagos, inclusive clientes sem pedido pago. A condição p.status=\'pago\' deve ficar, na forma usual com LEFT JOIN:', ['no ON da junção, junto da correspondência entre cliente e pedido.','somente no WHERE, sem aceitar NULL.','em HAVING COUNT(*)=0 para todos os grupos.','em ORDER BY para filtrar linhas.','em um INNER JOIN, que mantém todos os clientes automaticamente.'], 'O ON seleciona os pares pagos, e o LEFT JOIN preserva os clientes sem par. WHERE p.status=\'pago\' eliminaria linhas preenchidas com NULL.', ['O filtro rejeita as linhas sem par.','Não exprime o objetivo e COUNT(*) não seria zero nas linhas preservadas.','ORDER BY ordena; não filtra.','INNER JOIN elimina clientes sem correspondência.']))
lesson('db-normal','Normalização: encontre a dependência','A chave identifica a linha; dependências indevidas geram redundância e anomalias.', ['Uma dependência funcional X→Y diz que valores iguais de X determinam valores iguais de Y. Em chave composta, dependência de atributo não primo apenas de parte da chave viola a segunda forma normal.','Na terceira forma normal, para cada dependência não trivial X→A, X deve ser superchave ou A deve ser atributo primo. Na prática introdutória, dependências transitivas entre chave e atributos não chave costumam indicar necessidade de decomposição.'], 'Em Item(Pedido,Produto,NomeProduto,Quantidade), chave (Pedido,Produto), Produto→NomeProduto repete o nome em vários pedidos. Separar Produto(Produto,NomeProduto) de Item(Pedido,Produto,Quantidade) remove essa dependência parcial.', ['Declare a chave e as dependências.','Calcule se o determinante é toda a chave, parte dela ou outro atributo.','Separe a informação sobre uma entidade em sua relação.','Confira junção sem perda e restrições após decompor.'], 'Ter uma coluna chamada id não elimina automaticamente todas as dependências problemáticas.', 'Edital — Banco de Dados V.1')
pair('Banco de Dados','Dependência parcial','db-normal',case('Em R(Aluno,Disciplina,NomeAluno,Nota), a chave candidata é (Aluno,Disciplina), Aluno→NomeAluno e (Aluno,Disciplina)→Nota. NomeAluno não é atributo primo. A dependência indicada:', ['viola a 2FN por depender apenas de parte da chave composta.','viola a 1FN apenas por haver uma chave composta.','garante BCNF automaticamente.','é uma dependência multivalorada porque há dois atributos na chave.','não gera redundância possível porque existe chave candidata.'], 'NomeAluno depende de Aluno, parte própria da chave composta. A informação do aluno se repete em suas disciplinas; separar Aluno e matrícula/nota remove essa dependência parcial.', ['Chaves compostas são compatíveis com 1FN.','O determinante Aluno não é superchave de R.','Dependência funcional e multivalorada não se confundem dessa forma.','Chave candidata não impede outras dependências.']),case('Em R(Funcionario,Departamento,NomeDepartamento), Funcionario é a única chave candidata. Valem Funcionario→Departamento e Departamento→NomeDepartamento, e Departamento não é superchave. A decomposição usual é:', ['FuncionarioDepartamento(Funcionario,Departamento) e Departamento(Departamento,NomeDepartamento).','Remover Departamento e manter NomeDepartamento sem vínculo.','Duplicar NomeDepartamento em mais colunas.','Transformar NomeDepartamento em atributo multivalorado.','Criar uma chave artificial e manter tudo, garantindo automaticamente BCNF.'], 'A decomposição separa a descrição do departamento e remove a dependência transitiva de NomeDepartamento em relação à chave Funcionario.', ['Perde a identificação relacional necessária.','Amplia redundância.','Não trata a dependência funcional.','Uma nova chave não elimina a dependência Departamento→NomeDepartamento.']))
lesson('db-dw','Modelo dimensional: comece pela granularidade','A granularidade define o que uma linha da tabela fato representa.', ['Fatos guardam medidas de eventos em determinada granularidade; dimensões oferecem contextos como produto, tempo e local. Misturar granularidades pode duplicar totais ou comparar medidas incompatíveis.','No esquema estrela, dimensões costumam concentrar descrições; no snowflake, hierarquias dimensionais podem ser normalizadas em tabelas relacionadas. Medidas de fluxo, como valor de venda, podem ser aditivas em várias dimensões; saldos instantâneos geralmente não devem ser somados ao longo do tempo.'], 'Uma linha por item vendido permite somar faturamento por dia e produto. Uma linha com saldo diário de conta é uma fotografia: somar os saldos de segunda e terça não produz automaticamente um saldo significativo.', ['Descreva em uma frase o significado da linha fato.','Identifique as chaves das dimensões.','Classifique quais dimensões admitem soma da medida.','Evite joins que multipliquem fatos.'], 'Saldo em estoque é tipicamente semiaditivo: pode somar produtos/locais compatíveis, mas não instantes.', 'Edital — Banco de Dados V.1.5')
pair('Banco de Dados','Aditividade de medidas','db-dw',case('Uma fato registra o saldo de cada conta ao final de cada dia. A medida saldo é tipicamente:', ['semiaditiva: pode ser agregada entre contas compatíveis, mas a soma entre dias não representa o saldo de um instante.','sempre aditiva em todas as dimensões.','necessariamente textual e não numérica.','uma chave substituta da dimensão tempo.','um fato de transação que deve ser somado entre dias em qualquer análise.'], 'O saldo é uma medida de posição. Agregações temporais exigem definição, como saldo final ou média, e não soma indiscriminada dos snapshots.', ['Ignora a natureza de fotografia temporal.','Pode ser numérico sem ser totalmente aditivo.','É uma medida, não identificador de tempo.','Fotografia de saldo não é fluxo de transações.']),case('Em um modelo dimensional, a dimensão Produto contém chave de Categoria, e os atributos da categoria ficam em uma tabela própria ligada a Produto. Isso é característico de:', ['normalização de hierarquia dimensional, como em um esquema snowflake.','obrigatoriedade de todas as dimensões estarem em uma única tabela fato.','eliminação de qualquer dimensão do modelo.','proibição de consultas analíticas.','garantia de ausência de todas as junções.'], 'Separar níveis de uma hierarquia dimensional em relações caracteriza a estrutura em floco de neve. Ela altera as junções necessárias, não elimina o caráter dimensional.', ['Fato e dimensão têm papéis diferentes.','As dimensões continuam existindo.','O modelo continua permitindo consultas analíticas.','A normalização tende a acrescentar junções.']))
lesson('db-sql','Agregação, NULL e subconsultas','SQL tem etapas lógicas e valores desconhecidos: não trate NULL como um número comum.', ['WHERE filtra linhas antes do agrupamento; HAVING filtra grupos após a agregação. A comparação comum com NULL produz desconhecido, por isso use IS NULL ou IS NOT NULL quando essa for a pergunta.','NOT IN pode surpreender quando a lista contém NULL: se não houver correspondência, a presença de um valor desconhecido pode impedir que o predicado seja verdadeiro. NOT EXISTS com a correlação apropriada costuma expressar de forma direta a ausência de linha correspondente.'], 'Para listar clientes sem pedido, use NOT EXISTS em uma subconsulta ligada pelo cliente. Se uma lista de ids de pedidos contém NULL, id NOT IN (lista) pode não retornar os clientes esperados.', ['Decida se o filtro é de linha ou de grupo.','Verifique a possibilidade de NULL.','Expresse ausência com a correlação correta.','Teste um caso pequeno que contenha NULL.'], 'NULL não é igual a NULL por meio do operador =.', 'Edital — Banco de Dados V.2; semântica SQL de três valores')
pair('Banco de Dados','HAVING e agregação','db-sql',case('Deseja-se retornar departamentos cuja soma dos salários seja maior que 100.000, considerando apenas funcionários ativos. Os filtros de funcionário ativo e soma salarial pertencem, respectivamente, a:', ['WHERE e HAVING.','HAVING e WHERE.','ORDER BY e WHERE.','GROUP BY e ORDER BY.','SELECT e DISTINCT, sem agrupamento.'], 'WHERE restringe as linhas ativas antes do GROUP BY; HAVING restringe os grupos segundo SUM(salario).', ['Inverte filtro de linha e de grupo.','ORDER BY não seleciona linhas ativas.','Agrupar e ordenar não substituem os filtros.','DISTINCT não calcula a condição de soma por departamento.']),case('Para um valor não nulo x=3, avalia-se x NOT IN (1, 2, NULL) em um WHERE SQL. O resultado é que:', ['a linha não passa, pois o predicado resulta desconhecido.','a linha passa porque 3 é diferente de 1 e 2 e NULL é ignorado.','a linha passa porque NULL é tratado como zero.','a consulta necessariamente gera erro de sintaxe.','o predicado é sempre verdadeiro para qualquer x.'], '3 não coincide com 1 ou 2, mas a comparação com NULL é desconhecida. A negação permanece desconhecida, e WHERE mantém somente verdadeiro.', ['NOT IN não ignora NULL dessa maneira.','NULL não é convertido em zero.','A sintaxe é válida; o problema é semântico.','Há valores que correspondem à lista e outros que produzem desconhecido.']))
